package dev.sablelife.testing;
import dev.sablelife.SableLife;
import dev.sablelife.heart.*;
import dev.sablelife.ownership.LifeLifecycle;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.entity.ExperienceOrb;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder("sablelife_core_ui_tests") @PrefixGameTestTemplate(false)
public final class LevelRewardGameTests {
 @GameTest(template="combat",batch="xp_limits") public static void HundredLevelsAndThirtyThousandPointsValidateAndPersist(GameTestHelper h){var p=h.absolutePos(new BlockPos(3,4,3));h.getLevel().setBlockAndUpdate(p,SableLife.HEART.get().defaultBlockState());var core=(HeartBlockEntity)h.getLevel().getBlockEntity(p);var author=TestActors.creative(h.getLevel());h.assertTrue(core.editCore(author,"xp",30970,"")&&!core.editCore(author,"xp",30971,""),"Point boundary wrong");core.editCore(author,"xpLevels",1,"");h.assertTrue(core.displayedExperience()==100&&core.editCore(author,"xp",100,"")&&!core.editCore(author,"xp",101,"")&&!core.editCore(author,"xp",10.5,""),"Level boundary wrong");var copy=new HeartBlockEntity(p,core.getBlockState());copy.loadWithComponents(core.saveWithoutMetadata(h.getLevel().registryAccess()),h.getLevel().registryAccess());h.assertTrue(copy.deathExperienceLevels()&&copy.displayedExperience()==100&&copy.deathExperience()==30970,"Save lost upper reward");h.succeed();}
 @GameTest(template="combat",batch="xp_level_pickup") public static void CollectorGainsLevelsDirectlyAndPickupCannotRepeat(GameTestHelper h){var point=h.absoluteVec(new Vec3(3,7,3));LevelRewardOrb.award(h.getLevel(),point,10);var orb=h.getLevel().getEntitiesOfClass(LevelRewardOrb.class,new AABB(point,point).inflate(1)).getFirst();var saved=orb.saveWithoutId(new net.minecraft.nbt.CompoundTag());var restored=new LevelRewardOrb(SableLife.LEVEL_REWARD_ORB.get(),h.getLevel());restored.load(saved);h.assertTrue(restored.levels()==10,"Pickup reload lost amount");var player=TestActors.creative(h.getLevel());player.experienceLevel=40;player.experienceProgress=.35F;player.takeXpDelay=0;restored.playerTouch(player);h.assertTrue(player.experienceLevel==50&&Math.abs(player.experienceProgress-.35F)<.00001&&restored.isRemoved(),"Reward granted points instead of +10 levels");player.takeXpDelay=0;restored.playerTouch(player);h.assertTrue(player.experienceLevel==50,"Removed reward duplicated");orb.discard();h.succeed();}
 @GameTest(template="combat",batch="xp_no_merge") public static void LevelRewardsNeverMergeAndOrdinaryOrbsStillCan(GameTestHelper h)throws Exception{var orb=new LevelRewardOrb(SableLife.LEVEL_REWARD_ORB.get(),h.getLevel());var method=ExperienceOrb.class.getDeclaredMethod("canMerge",ExperienceOrb.class,int.class,int.class);method.setAccessible(true);h.assertTrue(!(boolean)method.invoke(null,orb,orb.getId(),0),"Level reward allowed merging");var ordinary=new ExperienceOrb(h.getLevel(),0,0,0,5);h.assertTrue((boolean)method.invoke(null,ordinary,ordinary.getId(),5),"Ordinary orb merging altered");h.succeed();}
 @GameTest(template="combat",batch="xp_death_job",timeoutTicks=30) public static void DeathDropsLevelRewardAndSavedJobsKeepMode(GameTestHelper h){var p=h.absolutePos(new BlockPos(3,6,3));h.getLevel().setBlockAndUpdate(p,SableLife.HEART.get().defaultBlockState());var core=(HeartBlockEntity)h.getLevel().getBlockEntity(p);var player=TestActors.creative(h.getLevel());core.editCore(player,"xpLevels",1,"");core.editCore(player,"xp",10,"");core.editCore(player,"delay",0,"");core.health().activate();core.forceDeath();var jobs=LifeLifecycle.get(h.getLevel().getServer()).save(new net.minecraft.nbt.CompoundTag(),h.getLevel().registryAccess());var reloaded=LifeLifecycle.load(jobs,h.getLevel().registryAccess()).save(new net.minecraft.nbt.CompoundTag(),h.getLevel().registryAccess());var entries=reloaded.getList("Deaths",10);boolean correct=false;for(int i=0;i<entries.size();i++){var job=entries.getCompound(i);if(job.getUUID("Id").equals(core.creatureId()))correct=job.getBoolean("ExperienceLevels")&&job.getInt("Experience")==160;}h.assertTrue(correct,"Death job lost level mode");h.runAfterDelay(10,()->{var orbs=h.getLevel().getEntitiesOfClass(LevelRewardOrb.class,new AABB(p).inflate(3));h.assertTrue(orbs.size()==1&&orbs.getFirst().levels()==10,"Death did not drop one direct-level reward");orbs.getFirst().discard();h.succeed();});}
}
